import { Dish } from "../types";

/**
 * Dishes bundled locally — exported from live Firestore `menu` on
 * 28 Nov 2026 (145 docs: Tasty Bites Dadu 104, Dadu Fast Food &
 * Kitchen 23, S M Bilal hotel 18; 144 available, 1 hidden).
 *
 * WHY: every first-time visitor used to run a full getDocs on
 * `menu` (~145 reads per load). At the Spark free tier's 50,000
 * reads/day that alone exhausts the quota — the app now reads
 * dishes from this file FIRST (0 Firestore reads) and only uses
 * Firestore as a fallback (delta says full re-fetch, or the
 * bundle is empty). Admin edits still reach users through the
 * catalogue delta (./catalogDelta.ts), which re-fetches only the
 * changed dish by ID — see LOCAL_DISHES_SYNCED_AT below.
 *
 * Names/descriptions are copied byte-for-byte from Firestore,
 * including the known live quirks (leading zero-width chars and
 * truncated "- Rs. 1," fragments on some Dadu Fast Food names).
 * Fixing those names is a separate rename task — do NOT silently
 * edit them here, or the bundle will drift from Firestore.
 *
 * Tuple order matches the app's display order (stable sort by
 * position, ties in Firestore order) so the first paint shows
 * the same menu order as a live fetch.
 */

interface DishExtras {
  discountPrice?: number;
  position?: number;
  isFeatured?: boolean;
  isBestseller?: boolean;
  openingTime?: string;
  closingTime?: string;
  commission?: number;
  sizes?: [name: string, price: number][];
  flavors?: [name: string, price: number][];
  addOns?: [name: string, price: number][];
}

type DishTuple = [
  id: string,
  name: string,
  description: string,
  price: number,
  category: string,
  imageUrl: string,
  restaurantName: string,
  isAvailable: boolean,
  extras?: DishExtras,
];

