/** Epoch ms when this bundle was exported from Firestore
 * (28 Nov 2026). Used as the `savedAt` when the app builds the
 * dish list from the bundle instead of Firestore, so the
 * catalogue delta only re-fetches admin changes made AFTER this
 * moment — anything earlier is already in the bundle. Update
 * this whenever the bundle is re-exported from Firestore. */
export const LOCAL_DISHES_SYNCED_AT = 1795853764642;

export const LOCAL_DISHES: Dish[] = RAW_DISHES.map(
  ([id, name, description, price, category, imageUrl, restaurantName, isAvailable, extras]) => ({
    id,
    name,
    description,
    price,
    category,
    imageUrl,
    restaurantName,
    isAvailable,
    type: "food",
    ...(extras?.discountPrice !== undefined ? { discountPrice: extras.discountPrice } : {}),
    ...(extras?.position !== undefined ? { position: extras.position } : {}),
    ...(extras?.isFeatured ? { isFeatured: true } : {}),
    ...(extras?.isBestseller ? { isBestseller: true } : {}),
    ...(extras?.openingTime ? { openingTime: extras.openingTime } : {}),
    ...(extras?.closingTime ? { closingTime: extras.closingTime } : {}),
    ...(extras?.commission !== undefined ? { commission: extras.commission } : {}),
    ...(extras?.sizes ? { sizes: extras.sizes.map(([sName, sPrice]) => ({ name: sName, price: sPrice })) } : {}),
    ...(extras?.flavors ? { flavors: extras.flavors.map(([fName, fPrice]) => ({ name: fName, price: fPrice })) } : {}),
    ...(extras?.addOns ? { addOns: extras.addOns.map(([aName, aPrice]) => ({ name: aName, price: aPrice })) } : {}),
  }),
);
